def lines(self, account, until=None, currency=None):
    """`account`'s lines, in date order, with their entries; only
    `currency`'s if one is given."""
    out = []
    for e in sorted(self.entries, key=lambda e: e.date):
        if until is not None and e.date > until:
            continue
        for line in e.lines:
            if line.account == account and (currency is None or line.currency == currency):
                out.append((e, line))
    return out

def balance(self, account, until=None, currency="USD"):
    """`account`'s balance in cents in `currency`, signed by its kind:
    positive is its normal side."""
    from .accounts import DEBIT_NORMAL

    raw = sum(line.cents for _, line in self.lines(account, until, currency))

